  const images = guide.photos.map((photo, i) => '<figure class="blr-photo"><img src="' + esc(photo[0]) + '" alt="' + esc(photo[1]) + '" loading="lazy" decoding="async"><figcaption>' + esc(photo[1]) + ' · <a href="' + esc(photo[2]) + '" target="_blank" rel="noopener noreferrer">Photo & licence</a></figcaption></figure>').join("");
  const itinerary = guide.itinerary.map((item, i) => '<li class="blr-timeline-item"><span class="blr-step">' + String(i+1).padStart(2,"0") + '</span><div><h3>' + esc(item[0]) + '</h3><p>' + esc(item[1]) + '</p></div></li>').join("");
  const highlights = guide.highlights.map(item => "<li>" + esc(item) + "</li>").join("");
  const cautions = guide.cautions.map(item => "<li>" + esc(item) + "</li>").join("");
  const pageTitle = "HiddenRides " + (guide.cityName || "Bengaluru") + " — " + guide.title + " ride guide";
